rast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;Selected candidates will complete a coding challenge focused on core programming and problem-solving&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;skills&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:180,&amp;quot;335559739&amp;quot;:180}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
